import { createRoute, z } from '@hono/zod-openapi'

const NonEmptyStringSchema = z
  .string()
  .regex(/.*\S.*/)
  .openapi('NonEmptyString')

const IntegerSchema = z.int().openapi('Integer')

const IpOrganizationDetailsSchema = z
  .object({
    Asn: IntegerSchema.and(
      z
        .any()
        .openapi({ description: 'The Autonomous System Number (ASN) of the internet provider' }),
    ).exactOptional(),
    AsnOrg: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the organization that registered the ASN.' }),
    ).exactOptional(),
    Isp: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The ISP information for the internet provider.' }),
    ).exactOptional(),
    Org: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the internet provider.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Provides information about an internet provider.', required: [] })
  .openapi('IpOrganizationDetails')

const CountrySchema = z
  .object({
    CountryCode: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The 2-letter ISO 3166 country code for the country.' }),
    ).exactOptional(),
    CountryName: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the country.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Information about a country.', required: [] })
  .openapi('Country')

const CitySchema = z
  .object({
    CityName: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the city.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Information about a city.', required: [] })
  .openapi('City')

const DoubleSchema = z.float64().openapi('Double')

const GeoLocationSchema = z
  .object({
    Lon: DoubleSchema.and(
      z.any().openapi({ description: 'The longitude of the location.' }),
    ).exactOptional(),
    Lat: DoubleSchema.and(
      z.any().openapi({ description: 'The latitude of the location.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Provides the latitude and longitude coordinates of a location.',
    required: [],
  })
  .openapi('GeoLocation')

const ActionRemoteIpDetailsSchema = z
  .object({
    IpAddressV4: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The IP address.' }),
    ).exactOptional(),
    Organization: IpOrganizationDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'The internet service provider (ISP) organization associated with the remote IP address.',
        }),
    ).exactOptional(),
    Country: CountrySchema.and(
      z.any().openapi({ description: 'The country where the remote IP address is located.' }),
    ).exactOptional(),
    City: CitySchema.and(
      z.any().openapi({ description: 'The city where the remote IP address is located.' }),
    ).exactOptional(),
    GeoLocation: GeoLocationSchema.and(
      z.any().openapi({ description: 'The coordinates of the location of the remote IP address.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'For <code>AwsApiAction</code>, <code>NetworkConnectionAction</code>, and <code>PortProbeAction</code>, <code>RemoteIpDetails</code> provides information about the remote IP address that was involved in the action.',
    required: [],
  })
  .openapi('ActionRemoteIpDetails')

const ActionRemotePortDetailsSchema = z
  .object({
    Port: IntegerSchema.and(
      z.any().openapi({ description: 'The number of the port.' }),
    ).exactOptional(),
    PortName: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The port name of the remote connection.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provides information about the remote port that was involved in an attempted network connection.',
    required: [],
  })
  .openapi('ActionRemotePortDetails')

const ActionLocalPortDetailsSchema = z
  .object({
    Port: IntegerSchema.and(
      z.any().openapi({ description: 'The number of the port.' }),
    ).exactOptional(),
    PortName: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The port name of the local connection.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'For <code>NetworkConnectionAction</code> and <code>PortProbeDetails</code>, <code>LocalPortDetails</code> provides information about the local port that was involved in the action.',
    required: [],
  })
  .openapi('ActionLocalPortDetails')

const BooleanSchema = z.boolean().openapi('Boolean')

const NetworkConnectionActionSchema = z
  .object({
    ConnectionDirection: NonEmptyStringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The direction of the network connection request (<code>IN</code> or <code>OUT</code>).',
        }),
    ).exactOptional(),
    RemoteIpDetails: ActionRemoteIpDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'Information about the remote IP address that issued the network connection request.',
        }),
    ).exactOptional(),
    RemotePortDetails: ActionRemotePortDetailsSchema.and(
      z.any().openapi({ description: 'Information about the port on the remote IP address.' }),
    ).exactOptional(),
    LocalPortDetails: ActionLocalPortDetailsSchema.and(
      z.any().openapi({ description: 'Information about the port on the EC2 instance.' }),
    ).exactOptional(),
    Protocol: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The protocol used to make the network connection request.' }),
    ).exactOptional(),
    Blocked: BooleanSchema.and(
      z
        .any()
        .openapi({ description: 'Indicates whether the network connection attempt was blocked.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provided if <code>ActionType</code> is <code>NETWORK_CONNECTION</code>. It provides details about the attempted network connection that was detected.',
    required: [],
  })
  .openapi('NetworkConnectionAction')

const AwsApiCallActionDomainDetailsSchema = z
  .object({
    Domain: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the DNS domain that issued the API call.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provided if <code>CallerType</code> is <code>domain</code>. It provides information about the DNS domain that issued the API call.',
    required: [],
  })
  .openapi('AwsApiCallActionDomainDetails')

const FieldMapSchema = z.record(z.string(), NonEmptyStringSchema).openapi('FieldMap')

const AwsApiCallActionSchema = z
  .object({
    Api: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The name of the API method that was issued.' }),
    ).exactOptional(),
    ServiceName: NonEmptyStringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The name of the Amazon Web Services service that the API method belongs to.',
        }),
    ).exactOptional(),
    CallerType: NonEmptyStringSchema.and(
      z
        .any()
        .openapi({
          description:
            'Indicates whether the API call originated from a remote IP address (<code>remoteip</code>) or from a DNS domain (<code>domain</code>).',
        }),
    ).exactOptional(),
    RemoteIpDetails: ActionRemoteIpDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provided if <code>CallerType</code> is <code>remoteIp</code>. Provides information about the remote IP address that the API call originated from.',
        }),
    ).exactOptional(),
    DomainDetails: AwsApiCallActionDomainDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provided if <code>CallerType</code> is <code>domain</code>. Provides information about the DNS domain that the API call originated from.',
        }),
    ).exactOptional(),
    AffectedResources: FieldMapSchema.and(
      z
        .any()
        .openapi({ description: 'Identifies the resources that were affected by the API call.' }),
    ).exactOptional(),
    FirstSeen: NonEmptyStringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>An ISO8601-formatted timestamp that indicates when the API call was first observed.</p> <p>A correctly formatted example is <code>2020-05-21T20:16:34.724Z</code>. The value cannot contain spaces, and date and time should be separated by <code>T</code>. For more information, see <a href="https://www.rfc-editor.org/rfc/rfc3339#section-5.6">RFC 3339 section 5.6, Internet Date/Time Format</a>.</p>',
        }),
    ).exactOptional(),
    LastSeen: NonEmptyStringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>An ISO8601-formatted timestamp that indicates when the API call was most recently observed.</p> <p>A correctly formatted example is <code>2020-05-21T20:16:34.724Z</code>. The value cannot contain spaces, and date and time should be separated by <code>T</code>. For more information, see <a href="https://www.rfc-editor.org/rfc/rfc3339#section-5.6">RFC 3339 section 5.6, Internet Date/Time Format</a>.</p>',
        }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provided if <code>ActionType</code> is <code>AWS_API_CALL</code>. It provides details about the API call that was detected.',
    required: [],
  })
  .openapi('AwsApiCallAction')

const DnsRequestActionSchema = z
  .object({
    Domain: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The DNS domain that is associated with the DNS request.' }),
    ).exactOptional(),
    Protocol: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The protocol that was used for the DNS request.' }),
    ).exactOptional(),
    Blocked: BooleanSchema.and(
      z.any().openapi({ description: 'Indicates whether the DNS request was blocked.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provided if <code>ActionType</code> is <code>DNS_REQUEST</code>. It provides details about the DNS request that was detected.',
    required: [],
  })
  .openapi('DnsRequestAction')

const ActionLocalIpDetailsSchema = z
  .object({
    IpAddressV4: NonEmptyStringSchema.and(
      z.any().openapi({ description: 'The IP address.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Provides information about the IP address where the scanned port is located.',
    required: [],
  })
  .openapi('ActionLocalIpDetails')

const PortProbeDetailSchema = z
  .object({
    LocalPortDetails: ActionLocalPortDetailsSchema.and(
      z.any().openapi({ description: 'Provides information about the port that was scanned.' }),
    ).exactOptional(),
    LocalIpDetails: ActionLocalIpDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provides information about the IP address where the scanned port is located.',
        }),
    ).exactOptional(),
    RemoteIpDetails: ActionRemoteIpDetailsSchema.and(
      z
        .any()
        .openapi({
          description: 'Provides information about the remote IP address that performed the scan.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'A port scan that was part of the port probe. For each scan, PortProbeDetails provides information about the local IP address and port that were scanned, and the remote IP address that the scan originated from.',
    required: [],
  })
  .openapi('PortProbeDetail')

const PortProbeDetailListSchema = z.array(PortProbeDetailSchema).openapi('PortProbeDetailList')

const PortProbeActionSchema = z
  .object({
    PortProbeDetails: PortProbeDetailListSchema.and(
      z.any().openapi({ description: 'Information about the ports affected by the port probe.' }),
    ).exactOptional(),
    Blocked: BooleanSchema.and(
      z.any().openapi({ description: 'Indicates whether the port probe was blocked.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Provided if <code>ActionType</code> is <code>PORT_PROBE</code>. It provides details about the attempted port probe that was detected.',
    required: [],
  })
  .openapi('PortProbeAction')

type ActionType = {
  ActionType?: z.infer<typeof NonEmptyStringSchema> & { [key: string]: unknown }
  NetworkConnectionAction?: z.infer<typeof NetworkConnectionActionSchema> & {
    [key: string]: unknown
  }
  AwsApiCallAction?: z.infer<typeof AwsApiCallActionSchema> & { [key: string]: unknown }
  DnsRequestAction?: z.infer<typeof DnsRequestActionSchema> & { [key: string]: unknown }
  PortProbeAction?: z.infer<typeof PortProbeActionSchema> & { [key: string]: unknown }
}

