export const postAdministratorRoute = createRoute({
  method: 'post',
  path: '/administrator',
  description:
    '<p>Accepts the invitation to be a member account and be monitored by the Security Hub administrator account that the invitation was sent from.</p> <p>This operation is only used by member accounts that are not added through Organizations.</p> <p>When the member account accepts the invitation, permission is granted to the administrator account to view findings generated in the member account.</p>',
  operationId: 'AcceptAdministratorInvitation',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              AdministratorId: z
                .string()
                .regex(/.*\S.*/)
                .openapi({
                  description:
                    'The account ID of the Security Hub administrator account that sent the invitation.',
                }),
              InvitationId: z
                .string()
                .regex(/.*\S.*/)
                .openapi({
                  description:
                    'The identifier of the invitation sent from the Security Hub administrator account.',
                }),
            })
            .openapi({ required: ['AdministratorId', 'InvitationId'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: AcceptAdministratorInvitationResponseSchema } },
    },
    480: {
      description: 'InternalException',
      content: { 'application/json': { schema: InternalExceptionSchema } },
    },
    481: {
      description: 'InvalidInputException',
      content: { 'application/json': { schema: InvalidInputExceptionSchema } },
    },
    482: {
      description: 'LimitExceededException',
      content: { 'application/json': { schema: LimitExceededExceptionSchema } },
    },
    483: {
      description: 'ResourceNotFoundException',
      content: { 'application/json': { schema: ResourceNotFoundExceptionSchema } },
    },
    484: {
      description: 'InvalidAccessException',
      content: { 'application/json': { schema: InvalidAccessExceptionSchema } },
    },
  },
})

